const fs=require('node:fs'),p=require('node:path'),c=require('node:crypto'),{createRequire}=require('node:module'),{execFileSync}=require('node:child_process');
const args=Object.fromEntries(process.argv.slice(2).map(x=>{const i=x.indexOf('=');return[x.slice(2,i),x.slice(i+1)]}));
const req=createRequire(p.resolve(args['asar-anchor'])),asar=req('@electron/asar');
const sha=b=>c.createHash('sha256').update(b).digest('hex');
function fileHash(file){const h=c.createHash('sha256'),fd=fs.openSync(file,'r'),b=Buffer.alloc(1024*1024);try{for(;;){const n=fs.readSync(fd,b,0,b.length,null);if(!n)break;h.update(b.subarray(0,n));}}finally{fs.closeSync(fd)}return h.digest('hex')}
function sectionHashes(file){const b=fs.readFileSync(file);if(b.subarray(0,2).toString()!=='MZ')throw Error('PE required');const off=b.readUInt32LE(0x3c),count=b.readUInt16LE(off+6),table=off+24+b.readUInt16LE(off+20),sections={};for(let i=0;i<count;i++){const q=table+40*i,name=b.subarray(q,q+8).toString().replace(/\0.*$/,''),size=b.readUInt32LE(q+16),start=b.readUInt32LE(q+20);sections[name]={bytes:size,sha256:sha(b.subarray(start,start+size))};}return{machine:b.readUInt16LE(off+4),sections};}
const root=p.resolve(args.root),archive=p.resolve(args.archive),header=asar.getRawHeader(archive).header,files={},packages={},outside={};
function walk(n,pre=''){for(const[name,e]of Object.entries(n.files).sort(([a],[b])=>a.localeCompare(b))){const rel=pre?pre+'/'+name:name;if(e.files){walk(e,rel);continue}if(e.link){files[rel]={link:e.link};continue}let data;const physical=archive+'.unpacked'+p.sep+rel.split('/').join(p.sep);const stat=e.unpacked?fs.statSync(physical):null;
 const f={bytes:e.size,sha256:e.unpacked?fileHash(physical):sha(data=asar.extractFile(archive,rel.split('/').join(p.sep))),unpacked:!!e.unpacked};
 if(process.platform!=='win32'&&e.unpacked)f.executable=!!(stat.mode&0o111);
 if(/\.(?:[cm]?js|json|html|css|svg|ts|map|md|txt|ya?ml)$/.test(rel)&&e.size<32*1024*1024){data??=e.unpacked?fs.readFileSync(physical):asar.extractFile(archive,rel.split('/').join(p.sep));const text=data.toString('utf8');f.lfSha256=sha(Buffer.from(text.replace(/\r\n/g,'\n')));if(rel.endsWith('/package.json')||rel==='package.json'){try{const j=JSON.parse(text);if(j.name&&j.version)packages[rel]={name:j.name,version:j.version};}catch{}}}
 files[rel]=f;
 }}walk(header);
if(process.platform==='darwin'){const framework=p.join(root,'Contents/Frameworks/Electron Framework.framework/Versions/A/Electron Framework'),info=p.join(p.dirname(framework),'Resources/Info.plist');outside.electronFramework={bytes:fs.statSync(framework).size,sha256:fileHash(framework),version:execFileSync('plutil',['-extract','CFBundleVersion','raw','-o','-',info],{encoding:'utf8'}).trim()};}
if(process.platform==='win32'){const exe=p.join(root,args.exe);outside.electronExecutable=sectionHashes(exe);outside.dlls={};for(const name of fs.readdirSync(root).filter(x=>x.toLowerCase().endsWith('.dll')).sort())outside.dlls[name]={bytes:fs.statSync(p.join(root,name)).size,sha256:fileHash(p.join(root,name))};}
const result={format:1,label:args.label,platform:process.platform,arch:process.arch,asarSha256:fileHash(archive),fileCount:Object.keys(files).length,packages,files,outside};fs.writeFileSync(args.output,JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({label:result.label,platform:result.platform,fileCount:result.fileCount,packages:Object.keys(packages).length,output:args.output}));
